            <ResponsiveContainer>
              <ScatterChart margin={{ top: 16, right: 24, left: 8, bottom: 16 }}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="Share"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  label={{ value: "Latest social rental %", position: "insideBottom", offset: -4 }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Change"
                  unit=" pp"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "pp change ~2010???latest",
                    angle: -90,
                    position: "insideLeft",
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[40, 280]} />
                <ReferenceLine y={0} stroke="#334155" />
                <ReferenceLine x={HEADLINE.oecdAverageSharePct} stroke="#94a3b8" strokeDasharray="4 4" />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v: number, name: string) => {
                    if (name === "x") return [`${v.toFixed(2)}%`, "Share"];
                    if (name === "y") return [`${v > 0 ? "+" : ""}${v.toFixed(2)} pp`, "Change"];
                    return [v, name];
                  }}
                  labelFormatter={(_, payload) =>
                    String(payload?.[0]?.payload?.full ?? "")
                  }
                />
                <Scatter data={scatterData}>
                  {scatterData.map((d) => (
                    <Cell key={d.name} fill={d.fill} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "bands" ? (
        <div className="grid gap-4 lg:grid-cols-2">
