          />
          Show OECD / EU average markers on share ladder
        </label>
      </div>

      {panel === "ladder" ? (
        <ChartCard
          title="Share ladder"
          subtitle="Social rental dwellings as % of total housing stock (latest QuASH year)"
        >
          <div style={{ width: "100%", height: chartHeight }}>
            <ResponsiveContainer>
              <BarChart
                layout="vertical"
