                <span className="font-semibold text-slate-800">{t.label}</span>
                {": "}
                {t.count} countries ??? {t.examples}
              </li>
            ))}
          </ul>
        </ChartCard>
      ) : null}

      {panel === "providers" ? (
        <ChartCard
          title="Provider mix"
          subtitle="% of each country???s social stock by provider type (not % of all dwellings)"
        >
