                  <Bar yAxisId="l" dataKey="share" name="Share %" fill={COLORS.moderate} />
                  <Line
                    yAxisId="r"
                    type="monotone"
                    dataKey="change"
                    name="?? pp"
                    stroke={COLORS.decline}
                    strokeWidth={2}
                    dot={{ r: 3 }}
                  />
                  <ReferenceLine
                    yAxisId="l"
                    y={HEADLINE.oecdAverageSharePct}
                    stroke={COLORS.oecd}
